      out.write("                    const selectedPrices = Array.from(priceFilters)\r\n");
      out.write("                        .filter(input => input.checked)\r\n");
      out.write("                        .map(input => input.getAttribute(\"data-price\"));\r\n");
      out.write("                    filterProductsByPrice(selectedPrices);\r\n");
