      out.write("                products.forEach(product => {\r\n");
      out.write("                    const productCategory = product.getAttribute(\"data-category\");\r\n");
      out.write("                    if (category === \"all\" || productCategory === category) {\r\n");
      out.write("                        product.style.display = \"block\";\r\n");
      out.write("                    } else {\r\n");
      out.write("                        product.style.display = \"none\";\r\n");
      out.write("                    }\r\n");
      out.write("                });\r\n");
      out.write("            }\r\n");
      out.write("\r\n");
      out.write("            // Hàm lọc sản phẩm theo giá\r\n");
      out.write("            function filterProductsByPrice(selectedPrices) {\r\n");
      out.write("                const products = document.querySelectorAll(\".product-item\");\r\n");
      out.write("                products.forEach(product => {\r\n");
      out.write("                    const productPrice = parseInt(product.getAttribute(\"data-price\"));\r\n");
